#!/bin/bash
# Generate a HEURISTIC warm-start corpus for the scalar-schema-v2
# lineage across the distributed cluster (desktop worker + Mac worker).
#
# Why this exists
# ---------------
# Measured 2026-09-24 on the strength ladder at nodes 100 / samples 2:
#
#   heuristic_pimc vs random  182-18   (wins)
#   s2 best net    vs random   68-132  (loses)
#   s2 v1          vs random    8-16   (loses)
#   heuristic_pimc vs the nets 191-9   (wins)
#
# Every s2 self-play shard so far was generated by the v1-driven agent,
# so the value targets are outcomes of games two incompetent agents
# played. This wrapper regenerates the corpus with the SAME PIMC search
# over the heuristic evaluator -- no weights, no torch -- emitting the
# identical npz schema (scalar-schema-v2 structured tokens,
# canonical_v2 action encoding, action-history tokens, value +
# visit-count targets, game_ids) so `mtg_bot train` consumes it
# unchanged.
#
# Usage
# -----
#   scripts/s2/gen_heuristic_corpus.sh [n_batches]
#
#   S2_GAMES_PER_BATCH=1500   games per launcher invocation
#   S2_CONFIG=configs/launch/s2.toml
#   S2_SEED=1
#   DRY_RUN=1                 print the resolved argv and exit
#
# Prereqs (see docs/RUNNING_DISTRIBUTED.md):
#   - coordinator up:  Start-ScheduledTask MTGBotCoordinatorS2  (:5099)
#   - desktop worker:  Start-ScheduledTask MTGBotWorkerLocal    (:5198)
#   - Mac worker:      launchd com.mtg-bot.worker
#   - EVERY worker must be running code that understands the
#     ``evaluator`` field on a claim. A worker on older code crashes on
#     every claim (the stage spec deliberately carries empty weights so
#     the old code's ``missing weights.p0`` guard fires) and the stage
#     yields zero samples -- loud, not silent. Run
#     ``POST /v2/self_update`` on each worker first.
#
# Batch indexing
# --------------
# --corpus-only never advances iterate_state.json's
# iterations_completed (there is no train and no promotion), so the
# wrapper cannot derive the stage id from the lineage counter the way
# run_distributed.sh does -- two invocations would reuse one stage id,
# the coordinator would answer 204 to every claim, and the run would
# silently produce nothing. Instead the batch index is derived from the
# heuristic shards already on disk and passed BOTH to the launcher
# (--iter.target_iter, which names the runs.db cycle row) and to
# iterate (--corpus-batch, which names the stage). That makes the
# wrapper resumable: re-running it picks up at the next free index.
set -euo pipefail
cd "/c/Users/Gregg Keithley/Documents/Claude/Projects/mtg-bot"
export PYTHONIOENCODING=utf-8 PYTHONPATH=src

N="${1:-1}"
CONFIG="${S2_CONFIG:-configs/launch/s2.toml}"
SEED="${S2_SEED:-1}"
GAMES="${S2_GAMES_PER_BATCH:-1500}"
DATA_DIR="${S2_DATA_DIR:-iterate_data_s2}"
PREFIX="s2_"

# Preflight: the coordinator on :5099 must be the s2 one. Heuristic
# stages don't fetch weights, but the SAME coordinator owns queue.db
# and rehydrates the artifacts into --data-dir, so pointing at the
# wrong one still mixes lineages.
if ! curl -sf -m 10 http://100.115.252.110:5099/v2/weights/v1/metadata \
    | grep -q '"scalar_schema_version": *2'; then
  echo "[s2-heur] ABORT: coordinator at :5099 is not serving trained_weights_s2" >&2
  exit 2
fi

next_batch() {
  # Highest NNN already present as <prefix>iter_NNN_self_play_heuristic*
  # in the data dir, plus one. Starts at iterations_completed + 1 so the
  # corpus stages never collide with the NN lineage's stage ids.
  python - "$DATA_DIR" "$PREFIX" <<'PY'
import json, re, sys
from pathlib import Path
data_dir, prefix = Path(sys.argv[1]), sys.argv[2]
state = json.load(open("trained_weights_s2/iterate_state.json"))
base = int(state["iterations_completed"])
pat = re.compile(re.escape(prefix) + r"iter_(\d+)_self_play_heuristic")
seen = [
    int(m.group(1))
    for p in data_dir.glob(f"{prefix}iter_*heuristic*")
    for m in [pat.match(p.name)] if m
]
print(max(seen + [base]) + 1)
PY
}

for _ in $(seq 1 "$N"); do
  target=$(next_batch)
  echo "[s2-heur] $(date -u +%FT%TZ) launching heuristic corpus batch $target ($GAMES games)"
  .venv-py313/Scripts/python.exe -m mtg_bot.cli iterate-distributed \
    --config "$CONFIG" --iter.target_iter "$target" \
    --iter.games_per_iteration "$GAMES" \
    --registry-root trained_weights_s2 --progress-dir training_progress_s2 \
    --deck-pool data/17lands/eoe_decks.json.gz \
    --queue-url http://100.115.252.110:5099 \
    ${DRY_RUN:+--dry-run} \
    --data-dir "$DATA_DIR" --scalar-schema-version 2 \
    --self-play-evaluator heuristic --corpus-only \
    --corpus-batch "$target" \
    --per-game-timeout-sec 900 --seed "$SEED"
  [ -n "${DRY_RUN:-}" ] && break
done

echo "[s2-heur] done. Train the warm-start net with e.g.:"
echo "  .venv-py313/Scripts/python.exe -m mtg_bot.cli train \\"
echo "    --data-dir $DATA_DIR --registry-root trained_weights_s2 \\"
echo "    --architecture structured --scalar-schema-version 2 \\"
echo "    --action-encoding-version canonical_v2 --epochs 20 \\"
echo "    --window-recent-files <n_heuristic_shards>"
